from __future__ import annotations as _annotations

from collections.abc import AsyncIterator, Callable
from contextlib import AsyncExitStack, asynccontextmanager, suppress
from dataclasses import dataclass, field
from functools import cached_property
from typing import TYPE_CHECKING, Any

from opentelemetry.trace import get_current_span

from pydantic_ai._run_context import RunContext
from pydantic_ai.models.instrumented import InstrumentedModel

from ..exceptions import FallbackExceptionGroup, ModelAPIError
from ..profiles import ModelProfile
from . import KnownModelName, Model, ModelRequestParameters, StreamedResponse, infer_model

if TYPE_CHECKING:
    from ..messages import ModelMessage, ModelResponse
    from ..settings import ModelSettings


class ResponseRejected(Exception):
    """Exception raised when a response is rejected by a response handler."""
    pass


@dataclass(init=False)
class FallbackModel(Model):
    """A model that uses one or more fallback models upon failure.

    Apart from `__init__`, all methods are private or match those of the base class.
    """

    models: list[Model]

    _model_name: str = field(repr=False)
    _fallback_on: Callable[[Exception], bool]

    def __init__(
        self,
        default_model: Model | KnownModelName | str,
        *fallback_models: Model | KnownModelName | str,
        fallback_on: Callable[[Exception], bool] | tuple[type[Exception], ...] = (ModelAPIError,),
    ):
        """Initialize a fallback model instance.

        Args:
            default_model: The name or instance of the default model to use.
            fallback_models: The names or instances of the fallback models to use upon failure.
            fallback_on: A callable or tuple of exceptions that should trigger a fallback.
        """
        super().__init__()
        self.models = [infer_model(default_model), *[infer_model(m) for m in fallback_models]]
        self._model_name = f"{self.models[0].model_name} -> {self.models[-1].model_name}"
        self._fallback_on = (
            lambda e: isinstance(e, fallback_on)
            if isinstance(fallback_on, tuple)
            else fallback_on
        )
        self._response_handler: Callable[[ModelResponse], bool] | None = None
        self._exception_handler: Callable[[Exception], bool] | None = None

    @cached_property
    def model_name(self) -> str:
        return self._model_name

    @cached_property
    def model_profile(self) -> ModelProfile:
        return ModelProfile(
            name=self.model_name,
            description=(
                f"A fallback model that tries {self.models[0].model_name} first, "
                f"then {self.models[-1].model_name} if the first fails."
            ),
        )

    def _fallback_on(self, exc: Exception) -> bool:
        """Check if the exception should trigger a fallback."""
        return self._fallback_on(exc)

    def _set_span_attributes(self, model: Model, prepared_parameters: Any) -> None:
        """Set span attributes for the current model."""
        _set_span_attributes(model, prepared_parameters)

    async def request(
        self,
        messages: list[ModelMessage],
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
    ) -> ModelResponse:
        exceptions: list[Exception] = []
        for model in self.models:
            try:
                _, prepared_parameters = model.prepare_request(
                    model_settings, model_request_parameters
                )
                response = await model.request(messages, model_settings, model_request_parameters)
                if self._response_handler is not None and self._response_handler(response):
                    raise ResponseRejected("Response rejected by response handler")
                if self._exception_handler is not None and self._exception_handler(response):
                    raise ResponseRejected("Response rejected by exception handler")
                self._set_span_attributes(model, prepared_parameters)
                return response
            except Exception as exc:
                if self._fallback_on(exc):
                    exceptions.append(exc)
                    continue
                raise exc
        raise FallbackExceptionGroup("All models from FallbackModel failed", exceptions)

    @asynccontextmanager
    async def request_stream(
        self,
        messages: list[ModelMessage],
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
        run_context: RunContext[Any] | None = None,
    ) -> AsyncIterator[StreamedResponse]:
        exceptions: list[Exception] = []
        for model in self.models:
            try:
                with AsyncExitStack() as stack:
                    _, prepared_parameters = model.prepare_request(
                        model_settings, model_request_parameters
                    )
                    async with stack.enter_async_context(
                        model.request_stream(
                            messages,
                            model_settings,
                            model_request_parameters,
                            run_context=run_context,
                        )
                    ) as response:
                        yield response
                        if self._response_handler is not None and self._response_handler(
                            response.get()
                        ):
                            raise ResponseRejected("Response rejected by response handler")
                        if self._exception_handler is not None and self._exception_handler(
                            response.get()
                        ):
                            raise ResponseRejected("Response rejected by exception handler")
                        self._set_span_attributes(model, prepared_parameters)
            except Exception as exc:
                if self._fallback_on(exc):
                    exceptions.append(exc)
                    continue
                raise exc
        raise FallbackExceptionGroup("All models from FallbackModel failed", exceptions)

    def prepare_request(
        self,
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
    ) -> tuple[ModelProfile, ModelRequestParameters]:
        """Prepare the request for the first model."""
        return self.models[0].prepare_request(model_settings, model_request_parameters)

    def with_response_handler(
        self, response_handler: Callable[[ModelResponse], bool]
    ) -> FallbackModel:
        """Set a response handler for the fallback model.

        Args:
            response_handler: A callable that takes a ModelResponse and returns a bool.
                If the callable returns True, the response is rejected and the next model is tried.
        """
        self._response_handler = response_handler
        return self

    def with_exception_handler(
        self, exception_handler: Callable[[Exception], bool]
    ) -> FallbackModel:
        """Set an exception handler for the fallback model.

        Args:
            exception_handler: A callable that takes an Exception and returns a bool.
                If the callable returns True, the exception is treated as a rejection and the next model is tried.
        """
        self._exception_handler = exception_handler
        return self


def fallback_condition(exc: Exception) -> bool:
    """Default fallback condition that checks for ModelAPIError."""
    return isinstance(exc, ModelAPIError)
